/* A navigable constellation; unlocked nodes remain available across runs. */
'use strict';
(function(){
 const T=JourneyTree,D=T.D;let browsing=false,returnHome=true,chosen='pow_atk_1',view={x:560,y:560,w:650},suppressClick=0;
 const label=n=>L(n.en,n.pt),owned=id=>id==='origin'||T.profile().unlocked.includes(id),type=n=>L({basic:'Basic',special:'Special',milestone:'Milestone',origin:'Origin'}[n.type],{basic:'Básico',special:'Especial',milestone:'Marco',origin:'Origem'}[n.type]);
 const symbol=n=>n.type==='milestone'?'✦':n.type==='special'?'◆':({sword:'⚔',heart:'♥',shield:'◇',haste:'»',boot:'↑',crit:'✧',coin:'◈',bag:'◈'}[n.icon]||'◆');
 function camera(){const svg=document.querySelector('.tree-graph');if(!svg)return;const r=svg.getBoundingClientRect(),h=view.w*r.height/Math.max(1,r.width);svg.setAttribute('viewBox',[view.x-view.w/2,view.y-h/2,view.w,h].join(' '));}
 function focus(id){const n=D.by[id];if(!n)return;chosen=id;view.x=n.x;view.y=n.y;view.w=Math.min(view.w,570);treeView();}
 function treeView(){const session=!browsing&&T.buying(S),xp=T.ensure(S)?.xp||0,n=D.by[chosen]||D.by.pow_atk_1,p=T.profile(),can=T.connected(n.id),unlocked=owned(n.id),edges=[];for(const a of [D.origin,...D.nodes])for(const id of a.links){if(a.id>id)continue;const b=D.by[id],bridge=D.bridges.some(pair=>pair.includes(a.id)&&pair.includes(id)),dx=b.x-a.x,dy=b.y-a.y;edges.push('<path class="'+(owned(a.id)&&owned(id)?'lit ':'')+(bridge?'bridge':'')+'" d="M'+a.x+' '+a.y+' Q'+((a.x+b.x)/2-dy*.12)+' '+((a.y+b.y)/2+dx*.12)+' '+b.x+' '+b.y+'"/>');}
 const nodes=[D.origin,...D.nodes].map(v=>{const state=owned(v.id)?'owned':T.connected(v.id)?'available':'locked',r=v.type==='origin'?29:v.type==='milestone'?25:v.type==='special'?20:15;return '<g tabindex="0" role="button" data-act="tree-node" data-id="'+v.id+'" class="tree-node '+state+' '+(chosen===v.id?'selected':'')+'" style="--node-color:'+(D.categories[v.category]?.color||'#edce86')+'" aria-label="'+esc(label(v)+' · '+type(v)+(v.cost?' · '+v.cost+' XP':'')+' · '+(state==='owned'?L('Unlocked','Desbloqueado'):state==='available'?L('Available','Disponível'):L('Locked','Bloqueado'))) +'" transform="translate('+v.x+' '+v.y+')"><circle class="tree-hit" r="27"/><circle class="tree-halo" r="'+(r+7)+'"/><circle class="tree-orb" r="'+r+'"/><text text-anchor="middle" dy="6" font-size="'+(v.type==='origin'?29:20)+'">'+(v.id==='origin'?'✧':symbol(v))+'</text></g>';}).join('');
 const headings=Object.entries(D.categories).map(([id,c])=>{const a=c.angle*Math.PI/180;return '<text class="tree-category-label" x="'+(560+Math.cos(a)*360)+'" y="'+(560+Math.sin(a)*360)+'" fill="'+c.color+'" text-anchor="middle">'+label(c).toUpperCase()+'</text>';}).join('');
 const requirement=unlocked?L('Permanent · active in your expeditions','Permanente · ativo nas suas expedições'):can?L('Connected · ready to unlock','Conectado · pronto para desbloquear'):L('Unlock any neighboring node first.','Desbloqueie qualquer node vizinho primeiro.');
 show('<section class="tree-screen"><div class="tree-title"><div><div class="eyebrow">'+L('PERMANENT PROGRESSION','PROGRESSÃO PERMANENTE')+'</div><h2>'+L('Skill Tree','Árvore de habilidades')+'</h2></div><div class="tree-balance"><b>'+xp+' XP</b><small>'+p.unlocked.length+'/60</small></div></div><nav class="tree-categories" aria-label="'+L('Branches','Categorias')+'">'+Object.entries(D.categories).map(([id,c])=>'<button data-act="tree-category" data-id="'+id+'" style="--branch:'+c.color+'">'+label(c)+'</button>').join('')+'</nav><div class="tree-viewport"><svg class="tree-graph" aria-label="'+L('Drag to explore. Zoom to inspect nodes.','Arraste para explorar. Amplie para inspecionar os nodes.')+'"><defs><radialGradient id="tree-orb"><stop stop-color="#244c60"/><stop offset="1" stop-color="#0c2032"/></radialGradient></defs><circle class="tree-ring" cx="560" cy="560" r="170"/><circle class="tree-ring" cx="560" cy="560" r="390"/><g class="tree-paths">'+edges.join('')+'</g>'+headings+nodes+'</svg><div class="tree-controls"><button data-act="tree-zoom" data-factor=".75" aria-label="'+L('Zoom in','Ampliar')+'">+</button><button data-act="tree-zoom" data-factor="1.33" aria-label="'+L('Zoom out','Reduzir')+'">−</button><button data-act="tree-center" aria-label="'+L('Center tree','Centralizar árvore')+'">⌾</button><button data-act="tree-fit">'+L('All','Tudo')+'</button></div><span class="tree-legend">'+L('Gold: unlocked · cyan: available','Ouro: desbloqueado · ciano: disponível')+'</span></div><div class="tree-picker"><span>'+L('Inspect','Inspecionar')+'</span><button data-act="tree-picker-open" aria-haspopup="dialog">'+(n.category?label(D.categories[n.category])+' · ':'')+label(n)+' <span>›</span></button></div><div class="training-sticky tree-footer"><div class="tree-selection"><div class="tree-node-title"><b>'+label(n)+'</b><span>'+type(n)+(n.cost?' · '+n.cost+' XP':'')+'</span></div><p>'+esc(n.id==='origin'?L('Choose any direction. You can freely develop several branches.','Escolha qualquer direção. Você pode desenvolver vários caminhos livremente.'):L(n.enDesc,n.ptDesc))+'</p><small>'+requirement+'</small></div><div class="tree-purchase">'+(session?metaButton('tree-buy',unlocked?'✓ '+L('Unlocked','Desbloqueado'):L('Unlock','Desbloquear')+' · '+n.cost+' XP',unlocked||!can||xp<n.cost?'disabled':'','primary'):'<small>'+L('Purchases open after each map Boss.','Compras liberadas após o Boss de cada mapa.')+'</small>')+'</div><div class="tree-exit">'+(session?metaButton('tree-continue',JourneyActs.act(S)===3?L('Finish journey','Concluir jornada'):L('Continue to map ','Avançar ao mapa ')+(JourneyActs.act(S)+1),'','secondary'):metaButton('tree-back',L('Back','Voltar'),'','primary'))+'</div><small class="tree-xp-note">'+(session&&JourneyActs.act(S)===3?L('Spend your XP before finishing. Unspent XP will be lost.','Gaste seu XP antes de concluir. O XP restante será perdido.'):L('Unlocked nodes persist. Unspent XP lasts only for this run.','Nodes desbloqueados são permanentes. O XP restante dura apenas esta run.'))+'</small></div></section>');
 document.querySelector('#screen-content').classList.add('tree-host');requestAnimationFrame(camera);const svg=document.querySelector('.tree-graph'),points=new Map();let last=null,dragged=false;
 svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});last={x:e.clientX,y:e.clientY};dragged=false;});
 svg.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;const old=[...points.values()];points.set(e.pointerId,{x:e.clientX,y:e.clientY});const now=[...points.values()],scale=view.w/svg.clientWidth;if(points.size===2){const d=Math.hypot(old[0].x-old[1].x,old[0].y-old[1].y),next=Math.hypot(now[0].x-now[1].x,now[0].y-now[1].y);view.w=Math.max(250,Math.min(1500,view.w*d/Math.max(1,next)));dragged=true;}else if(last){const dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.abs(dx)+Math.abs(dy)>2){dragged=true;svg.setPointerCapture(e.pointerId);}view.x-=dx*scale;view.y-=dy*scale;}last={x:e.clientX,y:e.clientY};camera();});
 function up(e){points.delete(e.pointerId);last=null;if(dragged)suppressClick=Date.now()+300;}
 svg.addEventListener('pointerup',up);svg.addEventListener('pointercancel',up);svg.addEventListener('wheel',e=>{e.preventDefault();view.w=Math.max(250,Math.min(1500,view.w*(e.deltaY>0?1.15:.87)));camera();},{passive:false});
 }
 function picker(category=D.by[chosen]?.category||'power'){const entries=D.nodes.filter(n=>n.category===category);journeyPanel(L('Inspect nodes','Inspecionar nodes'),'<nav class="node-picker-tabs">'+Object.entries(D.categories).map(([id,c])=>'<button class="'+(id===category?'active':'')+'" data-act="tree-picker-category" data-id="'+id+'" style="--branch:'+c.color+'">'+label(c)+'</button>').join('')+'</nav><div class="node-picker-list">'+[D.origin,...entries].map(n=>'<button data-act="tree-picker-select" data-id="'+n.id+'" class="node-picker-option '+(chosen===n.id?'chosen':'')+'"><span class="node-picker-mark">'+(owned(n.id)?'✓':T.connected(n.id)?'◇':'·')+'</span><span><b>'+label(n)+'</b><small>'+type(n)+(n.cost?' · '+n.cost+' XP':'')+' · '+(owned(n.id)?L('Unlocked','Desbloqueado'):T.connected(n.id)?L('Available','Disponível'):L('Locked','Bloqueado'))+'</small></span><span>›</span></button>').join('')+'</div>',metaButton('close',L('Back','Voltar'),'','primary'));}
 const baseRefresh=refreshMeta;refreshMeta=function(){if(document.querySelector('.tree-screen'))return treeView();return baseRefresh();};
 const baseRender=render;render=function(){if(S)T.resume(S);browsing=false;if(T.buying(S)){treeView();save();return;}return baseRender();};
 const baseHome=metaHomeButtons;metaHomeButtons=function(){return baseHome()+metaButton('tree-open',L('Skill Tree','Árvore de habilidades'));};
 const baseMenu=metaMenuButtons;metaMenuButtons=function(){return baseMenu()+(!battle||battle.result?metaButton('tree-open',L('Skill Tree','Árvore de habilidades')):'');};
 const baseMap=mapView;mapView=function(){baseMap();document.querySelector('.act-route-counts')?.insertAdjacentHTML('beforeend','<button class="tree-map-xp" data-act="tree-open">✧ '+(T.ensure(S)?.xp||0)+' XP</button>');};
 function pinContinue(){const button=document.querySelector('#screen-content [data-act=leave]');if(!button)return;const footer=document.createElement('div');footer.className='screen-footer';footer.append(button);document.querySelector('#app').append(footer);}
 const baseShop=shopView;shopView=function(){baseShop();pinContinue();if(T.has(S,'market')&&!T.shopState(S).freeUsed)document.querySelector('.shop-balance')?.insertAdjacentHTML('afterend',metaButton('tree-refresh',L('Refresh cards · free','Atualizar cartas · grátis')));};
 const baseRecruit=recruitView;recruitView=function(){baseRecruit();pinContinue();const state=T.recruitState(S);if(state?.chosen.length)document.querySelector('[data-act=leave]').textContent=L('Finish recruiting','Concluir recrutamento');if(state?.bonus)document.querySelector('.recruit-candidates')?.insertAdjacentHTML('beforebegin','<p class="tree-recruit-note">'+L('Caravan · choose up to ','Caravana · escolha até ')+state.remaining+L(state.remaining===1?' more different card.':' more different cards.',state.remaining===1?' carta diferente.':' cartas diferentes.')+'</p>');};
 const guard=JourneyTraining.guard;JourneyTraining.guard=function(e){const el=e.target.closest?.('[data-act]'),act=el?.dataset.act;if(!act?.startsWith('tree-'))return guard(e);if(e.type!=='click'&&!(e.type==='keydown'&&['Enter',' '].includes(e.key)))return guard(e);e.preventDefault();e.stopImmediatePropagation();if(act==='tree-node'&&Date.now()<suppressClick)return true;
 if(act==='tree-picker-open'){picker();}else if(act==='tree-picker-category'){picker(el.dataset.id);}else if(act==='tree-picker-select'){closeModal();focus(el.dataset.id);}else if(act==='tree-open'){returnHome=!!document.querySelector('.journey-home');closeModal();browsing=true;treeView();}else if(act==='tree-back'){browsing=false;returnHome?home():render();}else if(act==='tree-node')focus(el.dataset.id);else if(act==='tree-category'){const c=D.categories[el.dataset.id],a=c.angle*Math.PI/180;view={x:560+Math.cos(a)*260,y:560+Math.sin(a)*260,w:570};chosen=D.nodes.find(n=>n.category===el.dataset.id&&!owned(n.id)&&T.connected(n.id))?.id||D.nodes.find(n=>n.category===el.dataset.id).id;treeView();}else if(act==='tree-zoom'){view.w=Math.max(250,Math.min(1500,view.w*Number(el.dataset.factor)));camera();}else if(act==='tree-center'){view={x:560,y:560,w:650};camera();}else if(act==='tree-fit'){const svg=document.querySelector('.tree-graph');view={x:560,y:560,w:Math.max(1120,1120*svg.clientWidth/svg.clientHeight)};camera();}else if(act==='tree-buy'){if(!browsing&&T.buy(S,chosen)){save();treeView();}}else if(act==='tree-continue'){if(!browsing&&T.continueRun(S)){battle=null;runRaidPending=null;save();render();}}else if(act==='tree-refresh'){if(T.refreshShop(S)){save();render();}}return true;};
 window.addEventListener('resize',camera);
})();
